import AppKit

/// Space identification implemented via wallpaper images (beacons).
/// Assumes the beacon files have already been generated by FrameExtractor in beaconsDir under
/// the name "beacon-<uuid>.heic".
@MainActor
final class BeaconManager: BeaconManaging {
  private let beaconsDir: URL

  private static let prefix = "beacon-"
  private static let suffix = ".heic"
  private static let pollInterval: UInt64 = 100_000_000  // 100ms
  private static let pollTimeout: TimeInterval = 2.0

  init(beaconsDir: URL) {
    self.beaconsDir = beaconsDir
  }

  private func beaconFileURL(for uuid: UUID) -> URL {
    beaconsDir.appendingPathComponent(Self.prefix + uuid.uuidString + Self.suffix)
  }

  func setBeacon(_ uuid: UUID, on screen: NSScreen, scaling: ScalingMode) throws {
    let url = beaconFileURL(for: uuid)
    guard FileManager.default.fileExists(atPath: url.path) else {
      throw WallSceneError.beaconWriteFailed(
        String(localized: "Beacon image not found: \(url.path)"))
    }
    do {
      try NSWorkspace.shared.setDesktopImageURL(
        url, for: screen, options: Self.desktopImageOptions(for: scaling))
    } catch {
      throw WallSceneError.wallpaperSetFailed(error.localizedDescription)
    }
    Log.info(
      "beacon", "setBeacon uuid=\(uuid) screen=\(Self.screenKey(for: screen)) scaling=\(scaling)")
  }

  /// Expresses fill/fit through the options of NSWorkspace.setDesktopImageURL.
  /// - fill: scale up to cover the screen and crop (allowClipping=true). First-frame beacons for
  ///   videos/GIFs are usually hidden by the playback window right away, so this setting is
  ///   sufficient. When an image medium itself serves as the beacon, this directly becomes the
  ///   final appearance.
  /// - fit: scale up but do not crop (allowClipping=false). Margins become black bars via
  ///   fillColor.
  private static func desktopImageOptions(for scaling: ScalingMode) -> [NSWorkspace
    .DesktopImageOptionKey: Any]
  {
    switch scaling {
    case .fill:
      return [
        .imageScaling: NSImageScaling.scaleProportionallyUpOrDown.rawValue,
        .allowClipping: true,
      ]
    case .fit:
      return [
        .imageScaling: NSImageScaling.scaleProportionallyUpOrDown.rawValue,
        .allowClipping: false,
        .fillColor: NSColor.black,
      ]
    }
  }

  func peekBeaconUUID(on screen: NSScreen) -> UUID? {
    guard let url = NSWorkspace.shared.desktopImageURL(for: screen) else { return nil }
    return Self.parseBeaconUUID(from: url)
  }

  func currentBeaconUUID(on screen: NSScreen) async -> UUID? {
    let deadline = Date().addingTimeInterval(Self.pollTimeout)
    var lastNonBeaconURL: URL?
    var repeatCount = 0

    while true {
      if let url = NSWorkspace.shared.desktopImageURL(for: screen) {
        if let uuid = Self.parseBeaconUUID(from: url) {
          Log.info(
            "beacon",
            "currentBeaconUUID resolved uuid=\(uuid) screen=\(Self.screenKey(for: screen))")
          return uuid
        }
        if let lastNonBeaconURL, lastNonBeaconURL == url {
          repeatCount += 1
          if repeatCount >= 2 {
            // Same non-beacon URL observed twice in a row -> conclude early that it is not a beacon
            Log.info(
              "beacon",
              "currentBeaconUUID early-nil (non-beacon url stable) screen=\(Self.screenKey(for: screen))"
            )
            return nil
          }
        } else {
          lastNonBeaconURL = url
          repeatCount = 1
        }
      }

      if Date() >= deadline {
        Log.info("beacon", "currentBeaconUUID timeout screen=\(Self.screenKey(for: screen))")
        return nil
      }
      try? await Task.sleep(nanoseconds: Self.pollInterval)
    }
  }

  /// Extracts the UUID from a filename of the form "beacon-<UUID>.heic".
  /// UUID(uuidString:) accepts both upper- and lowercase, and percent-encoding has already been
  /// resolved on the URL API side.
  private static func parseBeaconUUID(from url: URL) -> UUID? {
    let name = url.lastPathComponent
    guard name.hasPrefix(prefix), name.hasSuffix(suffix) else { return nil }
    let start = name.index(name.startIndex, offsetBy: prefix.count)
    let end = name.index(name.endIndex, offsetBy: -suffix.count)
    guard start < end else { return nil }
    return UUID(uuidString: String(name[start..<end]))
  }

  private static func screenKey(for screen: NSScreen) -> String {
    screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")].map { "\($0)" } ?? "unknown"
  }
}
